from common import *
from collections import defaultdict
from audit import episodes

def main():
    o=json.loads((OUT/'metrics/original-evaluation.json').read_text());rm=json.loads(Path(CFG['raw_meta']).read_text());mappedconfig=json.loads((BASE/'metrics/training-config.json').read_text());rawconfig=json.loads((OUT/'metrics/original-training-config.json').read_text());oldhistory=json.loads((BASE/'metrics/training-history.json').read_text());best=min(oldhistory,key=lambda x:x['val_ce'])
    raw=load_data(OUT/'dataset/original/test');old=load_data(BASE/'dataset/test');ridx=np.load(OUT/'predictions/original-query-indices.npy');oldidx=np.load(OUT/'predictions/original-old-query-indices.npy');rp=np.load(OUT/'predictions/original-probabilities.npy',mmap_mode='r');mp=np.load(BASE/'predictions/M1-test-probabilities.npy',mmap_mode='r')
    spec=json.loads(Path(META['identity_mapping']).read_text());one={META['app_vocab'][r['mapped_app']]:rm['app_vocab'][r['lsapp_apps'][0]] for r in spec['mapping_rules'] if len(r['lsapp_apps'])==1};values=[];users=[];label_checks=0
    for row,(ri,mi) in enumerate(zip(ridx,oldidx)):
        pairs=[(ma,ra) for ma,ra in one.items() if old['eligible'][mi,ma] and raw['eligible'][ri,ra]]
        if len(pairs)<2:continue
        ma,ra=np.array(pairs).T
        # A one-to-one identity must have the same next entry and censor status.
        if not (np.array_equal(old['censored'][mi,ma],raw['censored'][ri,ra]) and np.allclose(old['remaining'][mi,ma],raw['remaining'][ri,ra],equal_nan=True)):
            raise AssertionError('one-to-one ground truth mismatch')
        label_checks+=len(pairs);scores=[mp[mi,ma].astype(float)@np.arange(8),rp[row,ra].astype(float)@np.arange(8)]
        metrics=query_metrics(range(len(pairs)),scores,raw['remaining'][ri,ra],raw['censored'][ri,ra],raw['observed_s'][ri]);values.append([[v[k] for k in KEYS] for v in metrics]);users.append(old['user'][mi])
    v=np.asarray(values).reshape(-1,2,len(KEYS));onesummary={'queries':len(v),'ground_truth_candidates_checked':label_checks,'reports':{'mapped':summary(v[:,0]),'original':summary(v[:,1])},'paired':paired(v[:,0],v[:,1],np.asarray(users)) if len(v) else {}}
    effective=episodes(raw,np.ones(len(raw['query_time']),bool),rm['app_vocab']);write(OUT/'metrics/original_effective_samples.json',effective);write(OUT/'metrics/one_to_one_comparison.json',onesummary);np.save(OUT/'metrics/one-to-one-query-metrics.npy',v)
    lines=['# Original LSApp versus mapped 30 apps','','Original model uses 87 real identities + PAD/UNKNOWN. Mapped model uses the existing 30 real identities + PAD/UNKNOWN. Original and mapped use EXACT same query timestamps/users and original split boundaries; query anchors are the frozen mapped-switch + 30s schedule, not separately resampled native anchors. Raw-zero-candidate anchors are omitted from raw arrays and linked by old_query_index; they contribute no classification supervision.','', 'The mapped M1 checkpoint is reused from the completed frozen 20-epoch run, whose seed, model family, history, loss, optimizer and query policy are unchanged. No duplicate retraining of an identical deterministic experiment is claimed. Vocabulary-dependent matrices change size (original parameters='+str(rawconfig['parameters'])+', mapped=77,656); encoder widths and layer structure remain unchanged.','', 'Main comparison below requires ≥2 candidates in BOTH spaces at the same query. Candidate identities/counts can differ, especially when one raw app maps to the mapped foreground or UNKNOWN. This is a comparison of full preprocessing pipelines, not a perfectly isolated causal estimate of semantic mapping.','', table(o['reports']['shared_multi']),'',f'Original best epoch={o["best_epoch"]}, validation CE={o["best_validation_ce"]:.6f}; mapped best epoch={best["epoch"]}, CE={best["val_ce"]:.6f}. Raw test observed episodes={effective["unique_reentry_episodes"]:,}. Eight output classes are the same, but different label distributions affect CE; it is not a directly normalized cross-task score.','', '## Same candidate identities and same truth: one-to-one mapping subset','',table(onesummary['reports']),'', 'Only targets with exactly one source identity are included; both models score the identical candidate set and verified identical return labels. This narrows coverage and may yield few comparable pairs; confidence intervals and counts are in metrics/one_to_one_comparison.json. It controls evaluation candidate/label differences, but training spaces still differ.','', 'Paired user-bootstrap across shared query times is in metrics/original-evaluation.json. Do not interpret the raw/mapped full-space difference alone as proving mapping is the dominant cause.']
    lines += ['', '## Interpretation of this frozen run', '',
              f'Full-space original POA={o["reports"]["shared_multi"]["M1-original"]["poa"]:.2%}, mapped={o["reports"]["shared_multi"]["M1-mapped-mixed"]["poa"]:.2%}; original-minus-mapped user-bootstrap CI={o["paired_comparison"]["shared_multi"]["poa"]["ci95"]}.',
              f'On {len(v):,} identical-candidate queries, original POA={onesummary["reports"]["original"]["poa"]:.2%}, mapped={onesummary["reports"]["mapped"]["poa"]:.2%}; CI={onesummary["paired"]["poa"]["ci95"]}. Neither scope establishes an original-space advantage; victim safety does not show a clear improvement either.',
              'These findings do not support mapping as the dominant performance bottleneck in this run. They do not prove equivalence or validate mapped smartphone events as real PC behavior. There is one training seed; vocabulary-dependent parameter counts and initialization draws differ, and the one-to-one subset covers only some applications. User-bootstrap intervals do not quantify training-seed variation.']
    (OUT/'ORIGINAL-VS-MAPPED.md').write_text('\n'.join(lines)+'\n');print('Original comparison PASS',flush=True)
if __name__=='__main__':main()
